<template>
  <main class="pricing-page"><header><div><p class="eyebrow">3B / ADMIN</p><h1>Pricing, offers & installments</h1><p>Schedule targeted campaigns, manage payment plans and preview customer pricing.</p></div><button @click="load">Refresh</button></header>
    <p v-if="error" class="notice error">{{ error }}</p><p v-if="notice" class="notice">{{ notice }}</p>
    <section class="panel"><h2>{{ editingId ? 'Edit campaign' : 'Create campaign' }}</h2><form class="form-grid" @submit.prevent="savePromotion">
      <label>Campaign name<input v-model="promo.name" required maxlength="160"></label><label>Discount type<select v-model="promo.discount_type"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label>
      <label>Discount value<input v-model.number="promo.discount_value" type="number" min="0.01" step="0.01" required></label><label>Priority<input v-model.number="promo.priority" type="number" min="0"></label>
      <fieldset class="targets-field"><legend>Campaign targets</legend><div v-for="(target, index) in promoTargets" :key="index" class="target-row"><select v-model="target.target_type" :aria-label="`Target type ${index + 1}`"><option v-for="type in targetTypes" :key="type" :value="type">{{ type }}</option></select><input v-model.number="target.target_id" type="number" min="1" required :aria-label="`Target record ID ${index + 1}`" placeholder="Record ID"><button v-if="promoTargets.length > 1" type="button" @click="removeTarget(index)">Remove</button></div><button type="button" @click="addTarget">Add another target</button></fieldset>
      <label>Badge (English)<input v-model="promo.badge_en"></label><label>Badge (Arabic)<input v-model="promo.badge_ar" dir="rtl"></label>
      <label>Starts at<input v-model="promo.starts_at" type="datetime-local"></label><label>Ends at<input v-model="promo.ends_at" type="datetime-local"></label>
      <label>Terms (English)<textarea v-model="promo.terms_en" rows="2"></textarea></label><label>Terms (Arabic)<textarea v-model="promo.terms_ar" rows="2" dir="rtl"></textarea></label>
      <label class="check"><input v-model="promo.is_active" type="checkbox"> Active</label><div class="actions"><button class="primary" :disabled="busy">{{ editingId ? 'Update campaign' : 'Create campaign' }}</button><button v-if="editingId" type="button" @click="resetPromo">Cancel edit</button></div>
    </form></section>
    <nav class="admin-shortcuts" aria-label="Admin pages"><NuxtLink to="/admin/catalog">Catalog</NuxtLink><NuxtLink to="/admin/taxonomy">Categories & specifications</NuxtLink><NuxtLink to="/admin/inventory">Inventory</NuxtLink><NuxtLink to="/admin/search">Search & comparison</NuxtLink></nav>
    <section class="panel"><h2>Promotion schedule</h2><div v-if="!scheduledPromotions.length" class="empty">No campaigns created yet.</div><article v-for="item in scheduledPromotions" :key="item.id" class="record"><div><strong>{{ item.name }}</strong><small>{{ item.discount_type }} {{ item.discount_value }} · priority {{ item.priority }} · {{ campaignState(item) }}</small><small>{{ item.targets.map(target => `${target.target_type} #${target.target_id}`).join(', ') }}</small><small>{{ item.starts_at || 'No start' }} → {{ item.ends_at || 'No end' }}</small></div><div><button @click="editPromotion(item)">Edit</button><button @click="deletePromotion(item.id)">Delete</button></div></article></section>
    <section class="panel"><h2>Effective price preview</h2><form class="inline-form" @submit.prevent="previewPrice"><input v-model.number="preview.product_id" type="number" min="1" required placeholder="Product ID"><input v-model.number="preview.variant_id" type="number" min="1" placeholder="Variant ID (optional)"><input v-model="preview.at" type="datetime-local"><button>Preview</button></form><div v-if="previewResult" class="preview"><strong>{{ money(previewResult.effective_price) }}</strong><del v-if="previewResult.savings">{{ money(previewResult.base_price) }}</del><span v-if="previewResult.promotion">{{ previewResult.promotion.name }}</span></div></section>
    <section class="panel"><h2>Installment providers</h2><form class="inline-form" @submit.prevent="saveProvider"><input v-model="provider.name" required placeholder="Provider name"><input v-model="provider.code" required placeholder="Code"><input v-model="provider.logo_url" type="url" placeholder="Logo URL"><input v-model="provider.terms_url" type="url" placeholder="Terms URL"><button :disabled="busy">Add provider</button></form><article v-for="item in providers" :key="item.id" class="record"><div><strong>{{ item.name }}</strong><small>{{ item.code }} · {{ item.is_active ? 'active' : 'paused' }}</small></div><button @click="toggleProvider(item)">{{ item.is_active ? 'Pause' : 'Activate' }}</button></article></section>
    <section class="panel"><h2>Add installment plan</h2><form class="form-grid" @submit.prevent="savePlan"><label>Provider<select v-model.number="plan.installment_provider_id" required><option disabled :value="0">Choose provider</option><option v-for="item in providers" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Plan name<input v-model="plan.name" required></label><label>Months<input v-model.number="plan.term_months" type="number" min="1" required></label><label>Minimum purchase<input v-model.number="plan.minimum_amount" type="number" min="0" step="0.01" required></label><label>Maximum purchase<input v-model.number="plan.maximum_amount" type="number" min="0" step="0.01"></label><label>Monthly fee (%)<input v-model.number="plan.monthly_fee_percentage" type="number" min="0" step="0.001" required></label><label>Starts at<input v-model="plan.starts_at" type="datetime-local"></label><label>Ends at<input v-model="plan.ends_at" type="datetime-local"></label><label class="check"><input v-model="plan.is_active" type="checkbox"> Active</label><button class="primary" :disabled="busy">Add plan</button></form><article v-for="item in providers.flatMap(provider => provider.plans || [])" :key="item.id" class="record"><div><strong>{{ item.name }}</strong><small>{{ providers.find(provider => provider.id === item.installment_provider_id)?.name }} · {{ item.term_months }} months · {{ item.monthly_fee_percentage }}% monthly</small></div><div><button @click="togglePlan(item)">{{ item.is_active ? 'Pause' : 'Activate' }}</button><button @click="deletePlan(item.id)">Delete</button></div></article></section>
    <section class="panel"><h2>Campaign performance</h2><div v-if="!performance.length" class="empty">No campaign-attributed sales yet.</div><table v-else><thead><tr><th>Campaign</th><th>Items</th><th>Units</th><th>Sales</th></tr></thead><tbody><tr v-for="row in performance" :key="row.promotion_id"><td>{{ row.promotion_name }}</td><td>{{ row.item_count }}</td><td>{{ row.units }}</td><td>{{ money(row.sales) }}</td></tr></tbody></table></section>
  </main>
</template>

<script setup lang="ts">
definePageMeta({ middleware: ['admin'], adminPermission: 'pricing.manage' })
const { request } = useApi()
const targetTypes = ['product', 'variant', 'category', 'brand', 'collection', 'coupon']
const promotions = ref<any[]>([]), providers = ref<any[]>([]), performance = ref<any[]>([]), busy = ref(false), error = ref(''), notice = ref(''), editingId = ref<number | null>(null), previewResult = ref<any>(null)
const scheduledPromotions = computed(() => [...promotions.value].sort((a, b) => new Date(a.starts_at || a.created_at).getTime() - new Date(b.starts_at || b.created_at).getTime()))
const emptyPromo = () => ({ name: '', discount_type: 'percentage', discount_value: 10, priority: 0, badge_en: '', badge_ar: '', terms_en: '', terms_ar: '', starts_at: '', ends_at: '', is_active: true })
const promo = reactive(emptyPromo()), provider = reactive({ name: '', code: '', logo_url: '', terms_url: '' })
const promoTargets = ref<Array<{ target_type: string, target_id: number }>>([{ target_type: 'product', target_id: 0 }])
const plan = reactive({ installment_provider_id: 0, name: '', term_months: 4, minimum_amount: 0, maximum_amount: null as number | null, monthly_fee_percentage: 0, starts_at: '', ends_at: '', is_active: true })
const preview = reactive({ product_id: 0, variant_id: null as number | null, at: '' })
const money = (value: number) => `${Number(value || 0).toLocaleString('en-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} EGP`
async function load() { error.value = ''; try { const data = await request('/admin/pricing'); promotions.value = data.promotions ?? []; providers.value = data.providers ?? []; performance.value = data.performance ?? [] } catch (e: any) { error.value = e?.data?.message ?? 'Could not load pricing settings.' } }
function dateValue(value: string) { return value ? new Date(value).toISOString() : null }
function promotionPayload() { return { ...promo, starts_at: dateValue(promo.starts_at), ends_at: dateValue(promo.ends_at), targets: promoTargets.value } }
async function savePromotion() { busy.value = true; error.value = ''; try { const response = await request(editingId.value ? `/admin/pricing/promotions/${editingId.value}` : '/admin/pricing/promotions', { method: editingId.value ? 'PUT' : 'POST', body: promotionPayload() }); notice.value = response.overlaps?.length ? `Saved. Overlaps with ${response.overlaps.map((item: any) => item.name).join(', ')}.` : 'Campaign saved.'; resetPromo(); await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not save campaign.' } finally { busy.value = false } }
function editPromotion(item: any) { editingId.value = item.id; Object.assign(promo, { ...emptyPromo(), ...item, starts_at: item.starts_at ? item.starts_at.slice(0, 16) : '', ends_at: item.ends_at ? item.ends_at.slice(0, 16) : '' }); promoTargets.value = item.targets?.length ? item.targets.map((target: any) => ({ target_type: target.target_type, target_id: target.target_id })) : [{ target_type: 'product', target_id: 0 }] }
function resetPromo() { editingId.value = null; Object.assign(promo, emptyPromo()); promoTargets.value = [{ target_type: 'product', target_id: 0 }] }
function addTarget() { promoTargets.value.push({ target_type: 'product', target_id: 0 }) }
function removeTarget(index: number) { if (promoTargets.value.length > 1) promoTargets.value.splice(index, 1) }
function campaignState(item: any) { if (!item.is_active) return 'paused'; if (item.starts_at && new Date(item.starts_at).getTime() > Date.now()) return 'scheduled'; if (item.ends_at && new Date(item.ends_at).getTime() <= Date.now()) return 'ended'; return 'active' }
async function deletePromotion(id: number) { try { await request(`/admin/pricing/promotions/${id}`, { method: 'DELETE' }); notice.value = 'Campaign deleted.'; await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not delete campaign.' } }
async function previewPrice() { error.value = ''; try { previewResult.value = (await request(`/admin/pricing/preview?product_id=${preview.product_id}${preview.variant_id ? `&variant_id=${preview.variant_id}` : ''}${preview.at ? `&at=${encodeURIComponent(new Date(preview.at).toISOString())}` : ''}`)).price } catch (e: any) { error.value = e?.data?.message ?? 'Could not calculate the preview.' } }
async function saveProvider() { busy.value = true; try { await request('/admin/pricing/providers', { method: 'POST', body: provider }); Object.assign(provider, { name: '', code: '', logo_url: '', terms_url: '' }); notice.value = 'Provider added.'; await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not add provider.' } finally { busy.value = false } }
async function toggleProvider(item: any) { try { await request(`/admin/pricing/providers/${item.id}`, { method: 'PUT', body: { is_active: !item.is_active } }); await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not update provider.' } }
async function savePlan() { busy.value = true; try { await request('/admin/pricing/plans', { method: 'POST', body: { ...plan, starts_at: dateValue(plan.starts_at), ends_at: dateValue(plan.ends_at) } }); notice.value = 'Installment plan added.'; Object.assign(plan, { name: '', starts_at: '', ends_at: '' }); await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not add installment plan.' } finally { busy.value = false } }
async function togglePlan(item: any) { try { await request(`/admin/pricing/plans/${item.id}`, { method: 'PUT', body: { is_active: !item.is_active } }); await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not update installment plan.' } }
async function deletePlan(id: number) { try { await request(`/admin/pricing/plans/${id}`, { method: 'DELETE' }); notice.value = 'Installment plan deleted.'; await load() } catch (e: any) { error.value = e?.data?.message ?? 'Could not delete installment plan.' } }
onMounted(load)
</script>

<style scoped>
.pricing-page{max-width:1180px;margin:0 auto;padding:34px 18px 64px;color:#182631}.pricing-page header{display:flex;justify-content:space-between;gap:16px;margin-bottom:22px}.eyebrow{margin:0;color:#2675d8;font-size:12px;font-weight:800;letter-spacing:.14em}h1{margin:5px 0;font-size:30px}h2{font-size:18px;margin:0 0 16px}.panel{background:white;border:1px solid #e0e6ea;border-radius:14px;padding:22px;margin:16px 0}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.form-grid label{display:flex;flex-direction:column;gap:6px;font-size:13px;color:#53616c}.form-grid input,.form-grid select,.form-grid textarea,.inline-form input{min-height:40px;border:1px solid #d5dde3;border-radius:8px;padding:8px 10px;font:inherit}.form-grid .check{flex-direction:row;align-items:center}.targets-field{grid-column:1/-1;display:grid;gap:10px;border:1px solid #d5dde3;border-radius:10px;padding:12px}.targets-field legend{padding:0 6px;color:#53616c;font-size:13px}.target-row{display:flex;gap:8px}.target-row select,.target-row input{flex:1;min-width:0;min-height:40px;border:1px solid #d5dde3;border-radius:8px;padding:8px 10px;font:inherit}.actions,.record>div:last-child{display:flex;gap:8px;align-items:center}.admin-shortcuts{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px}.admin-shortcuts a{color:#1769c2;font-weight:700}.panel button{border:1px solid #d5dde3;background:white;border-radius:8px;padding:9px 13px;cursor:pointer}.panel button.primary,.panel .primary{background:#1769c2;border-color:#1769c2;color:white}.inline-form{display:flex;gap:9px;flex-wrap:wrap}.inline-form input{flex:1;min-width:150px}.record{display:flex;justify-content:space-between;gap:12px;align-items:center;border-top:1px solid #e8ebef;padding:12px 0}.record strong,.record small{display:block}.record small{color:#64748b;margin-top:4px}.preview{display:flex;gap:14px;align-items:center;margin-top:16px}.preview strong{font-size:23px;color:#1769c2}.preview span{color:#64748b}.notice{padding:12px;border-radius:8px;background:#eff8f3;color:#087443}.notice.error{background:#fff1f0;color:#b42318}.empty{color:#64748b}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #edf0f2}@media(max-width:760px){.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pricing-page header{align-items:flex-start;flex-direction:column}}@media(max-width:500px){.form-grid{grid-template-columns:1fr}.targets-field{grid-column:auto}.panel{padding:16px}}
</style>
